func prepare() throws {
    guard !isPrepared else { return }
    try AVAudioSession.sharedInstance().setCategory(.playback, mode: .default)
    try AVAudioSession.sharedInstance().setActive(true)
    if !isConnected {
        audioEngine.attach(playerNode)
        audioEngine.connect(playerNode, to: audioEngine.mainMixerNode, format: nil)
        audioEngine.attach(rhythmNode)
        audioEngine.connect(rhythmNode, to: audioEngine.mainMixerNode,
                            format: AVAudioFormat(standardFormatWithSampleRate: 44_100, channels: 2))
        isConnected = true
    }

func loadPresets() throws -> [BeatPreset] {
    let userDefaults = try openStorage()
    guard let data = userDefaults.data(forKey: storageKey) else { return [] }

    do {
        return try JSONDecoder().decode([BeatPreset].self, from: data)
    } catch {
        userDefaults.removeObject(forKey: storageKey)
        throw error
    }
}

